return new{prefabMaterials=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(ThuyKieu.Player.Editor.ThuyKieuPlayableSetup.PrefabPath).GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>().SelectMany(r=>r.sharedMaterials).Select(m=>new{path=UnityEditor.AssetDatabase.GetAssetPath(m),texture=UnityEditor.AssetDatabase.GetAssetPath(m.mainTexture)}).ToArray(),cameraTarget=new UnityEditor.SerializedObject(UnityEngine.Camera.main.GetComponent<ThuyKieu.Player.ThirdPersonCameraController>()).FindProperty("target").objectReferenceValue.name};
